const atriumEdge = (x, z) =>
  ((x === ATRIUM.x0 - 1 || x === ATRIUM.x1 + 1) && z >= ATRIUM.z0 && z <= ATRIUM.z1) ||
  ((z === ATRIUM.z0 - 1 || z === ATRIUM.z1 + 1) && x >= ATRIUM.x0 && x <= ATRIUM.x1);
