/** stucco_wall(x0,z0,x1,z1,y0=2,y1=4): white_concrete fill. */
export function stucco_wall(g, x0, z0, x1, z1, y0 = 2, y1 = 4) {
  fill(g, [x0, y0, z0], [x1, y1, z1], WHITE_CONCRETE);
}

