    put(g, x, 2, 14, ...B.stairs("birch", "south", "bottom"));
    put(g, x, 2, 17, ...B.stairs("birch", "north", "bottom"));
  }

  // pendant lantern hung from the x=13 beam over the table centre
  put(g, 13, 4, 15, LANTERN, { hanging: "true" });
}

